// Direct-global y derivative: each thread produces one output. The 32 x
// threads of each warp address contiguous elements in a row.
__global__ void derivative_y(const float *f, float *df)
{
  const int x = blockIdx.x * blockDim.x + threadIdx.x;
  const int y = blockIdx.y * blockDim.y + threadIdx.y;
  const int z = blockIdx.z;
  if (x >= mx || y >= my || z >= mz) return;

  const int base = z * mx * my + x;

  // Match the baseline shared-memory halo for each individual offset:
  // negative indices wrap by my-1; indices past my-1 wrap by my-1,
  // while the endpoint at my-1 itself remains addressable.
  int ym1 = y - 1;
  if (ym1 < 0) ym1 += my - 1;
  int ym2 = y - 2;
  if (ym2 < 0) ym2 += my - 1;
  int ym3 = y - 3;
  if (ym3 < 0) ym3 += my - 1;
  int ym4 = y - 4;
  if (ym4 < 0) ym4 += my - 1;

  int yp1 = y + 1;
  if (yp1 >= my) yp1 -= my - 1;
  int yp2 = y + 2;
  if (yp2 >= my) yp2 -= my - 1;
  int yp3 = y + 3;
  if (yp3 >= my) yp3 -= my - 1;
  int yp4 = y + 4;
  if (yp4 >= my) yp4 -= my - 1;

  df[base + y * mx] =
    ( c_ay * ( f[base + yp1 * mx] - f[base + ym1 * mx] )
    + c_by * ( f[base + yp2 * mx] - f[base + ym2 * mx] )
    + c_cy * ( f[base + yp3 * mx] - f[base + ym3 * mx] )
    + c_dy * ( f[base + yp4 * mx] - f[base + ym4 * mx] ) );
}

