  df[idx] =
    ( c_ay * (f[rowBase + yp1 * mx] - f[rowBase + ym1 * mx])
    + c_by * (f[rowBase + yp2 * mx] - f[rowBase + ym2 * mx])
    + c_cy * (f[rowBase + yp3 * mx] - f[rowBase + ym3 * mx])
    + c_dy * (f[rowBase + yp4 * mx] - f[rowBase + ym4 * mx]) );
}

